using Qdrant.Client;
using Qdrant.Client.Grpc;

public class QdrantVectorService
{
    private readonly QdrantClient _client;
    private const string CollectionName = "tech_knowledge_base";

    public QdrantVectorService(string endpoint, string? apiKey = null)
    {
        _client = new QdrantClient(new Uri(endpoint), apiKey: apiKey);
    }

    public async Task EnsureCollectionExistsAsync(CancellationToken ct = default)
    {
        var collections = await _client.ListCollectionsAsync(ct);
        if (!collections.Contains(CollectionName))
        {
            await _client.CreateCollectionAsync(
                CollectionName,
                new VectorParams
                {
                    Size = 1536,
                    Distance = Distance.Cosine
                },
                hnswConfig: new HnswConfigDiff
                {
                    M = 16,               // Number of bi-directional links per node
                    EfConstruct = 100,    // Construction search depth
                    FullScanThreshold = 10000
                },
                cancellationToken: ct);
        }
    }

    public async Task<List<ScoredPoint>> QuerySimilarAsync(
        float[] queryVector,
        string departmentFilter,
        ulong limit = 5,
        CancellationToken ct = default)
    {
        // Filter matching department payload
        var filter = new Filter();
        filter.Must.Add(new Condition
        {
            Field = new FieldCondition
            {
                Key = "department",
                Match = new Match { Keyword = departmentFilter }
            }
        });

        IReadOnlyList<ScoredPoint> results = await _client.SearchAsync(
            CollectionName,
            queryVector,
            filter: filter,
            limit: limit,
            cancellationToken: ct);

        return results.ToList();
    }
}
